import sys; sys.path.insert(0, '.')
from mk2 import *
page(dict(
 slug='monkey',
 title=T('원숭이가 햄릿을 쓸 수 있을까', 'Can Monkeys Write Hamlet?'),
 title_tag=T('원숭이가 햄릿을 쓸 수 있을까 · 시뮬라티오 랩', 'Can Monkeys Write Hamlet? · Simulatio Lab'),
 desc=T('원숭이가 아무 글자나 쳐서 햄릿의 대사를 쓸 수 있을까요? 한 번에 맞히기와 조금씩 쌓기를 직접 겨뤄 보세요.',
        'Could monkeys typing random letters write a line of Hamlet? Race hitting it in one go against building it up step by step.'),
 lead=T('원숭이가 타자기를 무작위로 두드리면 언젠가 햄릿이 나온다는 "무한 원숭이 정리"가 있습니다. 하지만 "언젠가"는 얼마나 걸릴까요? 같은 목표를 "순수한 우연"과 "조금씩 나아지는 선택"으로 찾아가는 경주를 보여 드립니다.',
        'The "infinite monkey theorem" says that a monkey hitting typewriter keys at random will eventually produce Hamlet. But how long is "eventually"? Here is a race toward the same target, one side by pure chance and one by selection that improves little by little.'),
 model=[T('글자는 알파벳 대문자 26개와 띄어쓰기를 합친 27가지이고, 목표는 햄릿의 대사입니다(<code>TO BE OR NOT TO BE</code>, <code>METHINKS IT IS LIKE A WEASEL</code>).',
          'The symbols are the 26 uppercase letters plus the space, 27 in all, and the target is a line from Hamlet (<code>TO BE OR NOT TO BE</code> or <code>METHINKS IT IS LIKE A WEASEL</code>).'),
        T('<b style="color:var(--unlucky)">순수한 우연</b>: 한 단계마다 완전히 무작위인 문장 5,000개를 찍어 보고, 목표와 가장 많이 맞은 문장을 기록합니다. 이전 결과는 다음 시도에 아무 영향을 주지 않습니다.',
          '<b style="color:var(--unlucky)">Pure chance</b>: at every step, 5,000 completely random sentences are typed and the one matching the target in the most places is recorded. Earlier results have no influence on later attempts.'),
        T('<b style="color:var(--lucky)">누적 선택</b>: 무작위 문장 하나에서 시작해, 한 세대마다 복사본을 만들고 글자마다 일정 확률로 바꿉니다. 목표와 가장 많이 맞는 문장(부모 포함)이 다음 세대의 부모가 됩니다. 맞은 글자가 다음 세대로 이어지는 것이 차이입니다.',
          '<b style="color:var(--lucky)">Cumulative selection</b>: start from one random sentence; each generation makes copies and changes each letter with some probability. The sentence (parent included) matching the target in the most places becomes the next generation\'s parent. The difference is that correct letters are carried over.'),
        T('두 방식 모두 "목표와 맞은 글자 수"로만 평가합니다. 색칠된 글자 칸이 목표와 맞은 곳이에요.',
          'Both methods are scored only by "how many letters match the target." Highlighted letter boxes are the ones that match.')],
 sliders=[('offspring', T('한 세대의 복사본 수', 'Copies per generation'), 10, 200, 10, 100, T('누적 선택에서 한 번에 만드는 후보 수', 'How many candidates cumulative selection makes at once')),
          ('mutation', T('글자마다 바뀔 확률', 'Chance each letter changes'), 0.5, 10, 0.5, 5, T('돌연변이율이라고도 해요. 너무 낮으면 느리고, 너무 높으면 맞은 글자도 흔들려요', 'Also called the mutation rate. Too low is slow; too high shakes the correct letters too'))],
 selects=[('target', T('목표 문장', 'Target sentence'), [('tobe', T('TO BE OR NOT TO BE (18글자)', 'TO BE OR NOT TO BE (18 letters)')), ('weasel', T('METHINKS IT IS LIKE A WEASEL (28글자)', 'METHINKS IT IS LIKE A WEASEL (28 letters)'))], 'tobe',
           T('둘 다 햄릿의 대사예요', 'Both are lines from Hamlet'))],
 reroll=T('같은 설정, 다른 원숭이', 'Same settings, new monkeys'),
 sections=[
  dict(title=T('① 두 방식의 경주', '① The Race Between the Two Methods'),
       p=T('위쪽은 순수한 우연(빨강), 아래쪽은 누적 선택(초록)입니다. 색칠된 칸이 목표와 맞은 글자예요. 회색 줄은 우연이 방금 찍은 무작위 글자이고, 아래쪽의 옅은 줄들은 누적 선택에서 맞은 글자 수가 늘어날 때마다의 부모 문장입니다. 맞은 글자가 다음 세대로 이어지며 위에서 아래로 쌓여 가는 것을 보세요.',
           'The top is pure chance (red) and the bottom is cumulative selection (green). Colored boxes are letters that match the target. The gray row is the random text chance just typed, and the faint rows at the bottom are the parent sentences of cumulative selection each time the number of matching letters went up. Watch the correct letters carry over and pile up from top to bottom.'),
       id='c-text', rounded=True, anim=True, speeds=[('2', T('느리게', 'Slow')), ('6', T('보통', 'Normal')), ('20', T('빠르게', 'Fast'))], speed_default='6', thumb=True),
  dict(title=T('② 시도 횟수와 맞은 글자 수', '② Attempts and Letters Matched'),
       p=T('가로는 시도 횟수(로그 눈금), 세로는 맞은 글자 수입니다. 선택은 몇천 번 만에 끝나는데 우연은 100만 번을 찍어도 한참 모자랍니다.',
           'The horizontal axis is the number of attempts (log scale), the vertical axis is letters matched. Selection finishes in a few thousand attempts, while chance falls far short even after a million.'),
       id='c-race'),
  dict(title=T('③ 문장이 길어지면', '③ As the Sentence Gets Longer'),
       p=T('가로는 문장 길이, 세로는 성공에 필요한 시도 횟수(로그 눈금)입니다. 붉은 선은 우연의 기댓값(27<sup>L</sup>), 파란 점은 선택을 6번씩 돌린 결과예요.',
           'The horizontal axis is sentence length, the vertical axis is the number of attempts needed (log scale). The red line is chance\'s expected value (27<sup>L</sup>), and the blue dots are 6 runs of selection each.'),
       id='c-expect', note='expect'),
  dict(title=T('④ 돌연변이율을 바꾸면', '④ When the Mutation Rate Changes'),
       p=T('가로는 글자가 바뀔 확률(돌연변이율), 세로는 완성에 걸린 세대 수입니다. 점은 6번의 실행이에요.',
           'The horizontal axis is the chance a letter changes (the mutation rate), the vertical axis is the number of generations until completion. Dots are 6 runs.'),
       id='c-mut', note='mut'),
 ],
 says=T('목표를 한 번에 맞히려는 우연은 문장이 길어질수록 기대 시도 횟수가 27배씩 불어나서 사실상 불가능해지지만, 맞은 글자를 이어 가는 누적 선택은 몇천 번 만에 같은 문장에 도달합니다. 같은 우연이라도 "한 번에 다 맞히기"와 "조금씩 쌓기"는 전혀 다른 일이에요.',
        'For chance trying to hit the target in one go, the expected number of attempts grows 27-fold with every added letter, which makes it practically impossible. Cumulative selection, which keeps the letters it got right, reaches the same sentence in a few thousand attempts. Even with the same randomness, "getting everything right at once" and "building up step by step" are completely different things.'),
 **{'not': T('실제 생물의 진화가 이 프로그램처럼 일어난다는 뜻이 아닙니다. 이 모델에는 미리 정해진 목표 문장이 있지만 진화에는 정해진 목표가 없고, 도킨스 자신도 이 점을 밝혔습니다. 이 실험은 "한 번에 맞히는 우연"과 "단계마다 걸러 내는 선택"의 힘의 차이만 보여줍니다. 원숭이가 실제로 햄릿을 쓰는지에 대한 이야기도 아닙니다.',
             'It does not mean real biological evolution works like this program. The model has a preset target sentence, whereas evolution has no set goal, a point Dawkins himself made. This experiment only shows the difference in power between "chance that must hit in one go" and "selection that filters at every step." It is also not a claim about whether monkeys could actually write Hamlet.')},
 theory=[
  ('root', T('타자기를 치는 원숭이 비유는 Émile Borel (1913)까지 거슬러 올라간다고 흔히 인용됩니다. 한편 Richard Dawkins (1986)는 『The Blind Watchmaker』에서 "위즐 프로그램"으로, 우연은 아득히 오래 걸리지만 작은 개선을 쌓아 가는 누적 선택은 훨씬 빠르다는 점을 보였습니다.',
             'The typing-monkey metaphor is commonly traced back to Émile Borel (1913). Richard Dawkins (1986), in <i>The Blind Watchmaker</i>, used his "weasel program" to show that chance takes unimaginably long, while cumulative selection that keeps small improvements is far faster.')),
  ('model', T('글자 27가지에서 무작위로 L글자를 치면 한 번에 정확히 맞힐 확률은 <code>27<sup>-L</sup></code>이라 기대 시도 횟수는 대략 <code>27<sup>L</sup></code>입니다. 누적 선택은 복사본 여러 개를 만들고 글자마다 일정 확률로 바꾼 뒤 가장 많이 맞은 복사본만 남깁니다. 복사본 수와 돌연변이율이 슬라이더이고, 글자 수가 늘어도 필요한 시도는 27의 거듭제곱이 아니라 훨씬 완만하게 늘어납니다.',
             'Typing L random symbols from 27 gets it exactly right with probability <code>27<sup>-L</sup></code>, so the expected number of attempts is roughly <code>27<sup>L</sup></code>. Cumulative selection makes several copies, changes each letter with some probability, and keeps only the copy with the most matches. The number of copies and the mutation rate are the sliders, and as the sentence grows the attempts needed grow far more gently than a power of 27.')),
  ('simplify', T('Dawkins 본인이 밝혔듯 위즐 프로그램은 미리 정한 목표가 있어서 실제 진화(목표가 없음)의 모형이 아니고 누적 선택이 위력적이라는 점만 보여 주는 비유입니다. 책의 프로그램과 세부 설정이 다르며, 복사본 100개, 돌연변이 5%, 대문자와 띄어쓰기만 쓴 것, 초당 10억 번 시도는 이 프로젝트가 정한 값입니다.',
                'As Dawkins himself noted, the weasel program has a fixed target, so it is not a model of real evolution (which has no target) and only illustrates how powerful cumulative selection is. Its details differ from the book\'s program, and 100 copies, 5% mutation, capital letters and space only, and one billion attempts per second are values this project chose.')),
  ('check', T('우연의 기대 횟수는 닫힌 식이라 계산이 맞습니다. 18글자 27<sup>18</sup> ≈ 5.8×10<sup>25</sup>번은 초당 10억 번이면 약 18억 년(우주 나이 138억 년의 0.13배), 28글자 27<sup>28</sup> ≈ 1.2×10<sup>40</sup>번은 약 3.8×10<sup>23</sup>년이고 validate 출력과 같습니다. 누적 선택은 닫힌 해가 없어 시뮬레이션만으로 확인했고, 기본 설정에서 18글자는 평균 46세대, 28글자는 평균 77세대(20회)였고, 선택 쪽 시도 횟수는 3글자 약 1,000번에서 18글자 약 5,000번으로만 늘었습니다.',
                'The expected count for chance is a closed form and the calculation holds. For 18 letters 27<sup>18</sup> ≈ 5.8×10<sup>25</sup> attempts at a billion per second take about 1.8 billion years (0.13 of the universe\'s 13.8 billion), and for 28 letters 27<sup>28</sup> ≈ 1.2×10<sup>40</sup> attempts take about 3.8×10<sup>23</sup> years, matching the validate output. Cumulative selection has no closed form and was checked by simulation only: with defaults, 18 letters took 46 generations and 28 letters 77 on average (20 runs), and the attempts under selection rose only from about 1,000 at 3 letters to about 5,000 at 18.')),
  ('read', T('Dawkins (1986), 『The Blind Watchmaker』, Longman(3장). 무한 원숭이 정리는 확률론 교재의 Borel–Cantelli 보조정리 부분에서 다룹니다.',
             'Dawkins (1986), <i>The Blind Watchmaker</i>, Longman (chapter 3). The infinite monkey theorem is covered in probability textbooks under the Borel–Cantelli lemmas.')),
 ],
 memo=[T('이 프로젝트가 직접 짠 구현이며 책의 프로그램을 그대로 옮긴 것은 아닙니다.',
          'This is this project\'s own implementation, not a literal port of the program in the book.'),
        T('목표 문장은 햄릿의 대사입니다: "To be, or not to be"(3막 1장)와 "Methinks it is like a weasel"(3막 2장). 글자는 알파벳 대문자 26개와 띄어쓰기이고 쉼표 같은 부호는 뺐습니다.',
          'The targets are lines from Hamlet: "To be, or not to be" (Act 3, Scene 1) and "Methinks it is like a weasel" (Act 3, Scene 2). The symbols are the 26 uppercase letters and the space; punctuation such as commas is left out.'),
        T('기본 설정(복사본 100개, 돌연변이율 5%)으로 20번 돌리면 <code>TO BE OR NOT TO BE</code>는 평균 46세대(최소 26, 최대 89), <code>METHINKS IT IS LIKE A WEASEL</code>은 평균 77세대(최소 43, 최대 116)가 걸렸습니다. 우연은 100만 번을 찍어도 각각 7/18, 9/28 정도만 맞았습니다.',
          'With the default settings (100 copies, 5% mutation), 20 runs took on average 46 generations (min 26, max 89) for <code>TO BE OR NOT TO BE</code> and 77 generations (min 43, max 116) for <code>METHINKS IT IS LIKE A WEASEL</code>. After a million attempts, chance had matched only about 7/18 and 9/28.'),
        T('우연으로 L글자를 한 번에 맞힐 기대 시도 횟수는 27<sup>L</sup>입니다. "초당 10억 번 시도"는 이 프로젝트의 가정이고, 우주 나이는 약 138억 년으로 계산했습니다. 18글자는 약 18억 년(우주 나이의 0.13배), 28글자는 약 3.8×10<sup>23</sup>년입니다.',
          'The expected number of attempts to hit an L-letter sentence by chance in one go is 27<sup>L</sup>. "One billion attempts per second" is this project\'s assumption, and the age of the universe is taken as about 13.8 billion years. For 18 letters that is about 1.8 billion years (0.13 times the age of the universe); for 28 letters, about 3.8×10<sup>23</sup> years.'),
        T('문장이 아주 짧을 때(1~2글자)는 이 설정의 누적 선택이 오히려 우연보다 느립니다. 글자마다 5%만 바뀌기 때문에 복사본 100개로도 변화가 드물기 때문입니다. 검증은 <code>node tools/validate-monkey.js</code>로 할 수 있습니다.',
          'For very short sentences (1 to 2 letters), cumulative selection with these settings is actually slower than chance, because with only 5% of letters changing, even 100 copies rarely differ. You can verify with <code>node tools/validate-monkey.js</code>.')],
))
